<?php namespace App\Features\Profile\Livewire;use Livewire\Component;use Livewire\WithFileUploads;use App\Features\Profile\Services\ProfileService;
class Profile extends Component{use WithFileUploads;public string $name='';public string $username='';public string $email='';public string $password='';public string $password_confirmation='';public $photo;public function mount(){foreach(['name','username','email'] as $f)$this->$f=auth()->user()->$f;}public function save(ProfileService $service){$data=$this->validate(['name'=>'required|string|max:100','username'=>'required|string|max:30|unique:users,username,'.auth()->id(),'email'=>'required|email|unique:users,email,'.auth()->id(),'password'=>'nullable|min:8|confirmed','photo'=>'nullable|image|max:2048']);if($this->photo)$data['profile_photo_path']=$this->photo->store('profiles','public');unset($data['photo']);$service->update(auth()->user(),$data);session()->flash('success','Profil diperbarui.');}public function render(){return view('livewire.profile.profile')->layout('components.layouts.app');}}
